sys_script_include.script:
var AppointmentUtils1 = Class.create();
AppointmentUtils1.prototype = {
    initialize: function() {},
    fetchAppointments: function(aptid) {
        var gr = new GlideRecord("u_appointment");
        gr.addQuery("number", aptid); // <-- Match by Appointment ID, not sys_id
        gr.query();
        if (!gr.get(aptid)) {
            throw 'Patient not found for sys_id: ' + aptid;
        }
        // build the result
        return {
            date: gr.getValue('u_appointment_date'),
            department: gr.getValue("u_department")
        };
    },

    // 	if (gr.get(aptid)) {
    //         return {
    //             Date: gr.getValue("u_appointment_date"),
    //             Department: gr.getValue("u_department")
    //         };
    //     } else {
    //         return {
    //             error: "Appointment not found"
    //         };
    //     }
    // },
    type: 'AppointmentUtils1'
};
